    public Settings prepare_save(Control o){var document=Document(o);string destination=o.Get("document_path").AsString();return new Settings{["session"]=Session(o),["document"]=document,["destination"]=destination,["pick"]=destination.Length==0,["extension"]=Dict(document,"portable_media").Count>0?"res":"tres",["title"]=document.Get("title")};}
    public Resource save_snapshot(Control o){capture_state(o);return Document(o).Call("snapshot").As<Resource>();}
    public void complete_save(Control o,Settings request,Settings target)
    {
        string destination=request["destination"].AsString();if(request["pick"].AsBool()){if(Session(o)!=request["session"].AsGodotObject()||Document(o)!=request["document"].AsGodotObject()){notice(o,"The active composition changed while choosing a save path. Save again in the intended document.");return;}if(target.Count==0)return;destination=Get(target,"path","").AsString();if(destination.Length==0)return;}capture_state(o);string error=Document(o).Call("midi_timing_error").AsString();if(error.Length>0){notice(o,error);return;}var snapshot=Document(o).Call("snapshot").As<Resource>();using var portable=new AudioPortableOperations();var prepared=portable.for_save(snapshot,destination);if(Get(prepared,"error","").AsString().Length>0){notice(o,prepared["error"].AsString());return;}var saved=save_document(prepared["document"].As<Resource>(),destination);if(saved!=Error.Ok){notice(o,"Audio composition could not be saved ("+saved+").");return;}o.Set("document_path",destination);o.Set("source",destination);o.Set("path",destination);Session(o).Set("dirty",false);o.EmitSignal("audio_saved",destination);refresh_all(o);Field<Label>(o,"status").Text="Saved editable audio composition.";o.Call("_refresh_project_filesystem");
    }
    public Error save_document(Resource? document,string destination)
    {
        if(document==null||document.Call("validate").AsStringArray().Length>0)return Error.InvalidData;using var portable=new AudioPortableOperations();var prepared=portable.for_save(document,destination);if(Get(prepared,"error","").AsString().Length>0)return Error.InvalidData;document=prepared["document"].As<Resource>();string extension=destination.GetExtension().ToLowerInvariant();if(extension is not ("tres" or "res"))return Error.FileUnrecognized;string absolute=ProjectSettings.GlobalizePath(destination);var error=DirAccess.MakeDirRecursiveAbsolute(absolute.GetBaseDir());if(error!=Error.Ok)return error;using var crypto=new Crypto();string temporary=absolute.GetBaseName()+".kiwi-saving-"+Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant()+"."+extension;error=ResourceSaver.Save(document,temporary);if(error!=Error.Ok){if(Godot.FileAccess.FileExists(temporary))DirAccess.RemoveAbsolute(temporary);return error;}string backup=absolute+".bak";if(Godot.FileAccess.FileExists(absolute)){if(Godot.FileAccess.FileExists(backup)){string previous=backup+"."+Time.GetUnixTimeFromSystem().ToString("G17",CultureInfo.InvariantCulture).Replace('.','_');var moved=DirAccess.RenameAbsolute(backup,previous);if(moved!=Error.Ok)return moved;}error=DirAccess.RenameAbsolute(absolute,backup);if(error!=Error.Ok)return error;}error=DirAccess.RenameAbsolute(temporary,absolute);if(error!=Error.Ok&&Godot.FileAccess.FileExists(backup))DirAccess.RenameAbsolute(backup,absolute);return error;
    }
    public AudioStream? workspace_source(Variant value){var audio=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs");return audio.Call("needs_file_preview",value).AsBool()?null:audio.Call("source",value).AsGodotObject() as AudioStream;}
    public bool requires_exact_preview(Control o)
    {
        var document=Document(o);var audio=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs");using var edits=new AudioEditSessionOperations();foreach(var raw in Items(document,"actors")){var actor=raw.AsGodotObject();var values=actor.Get("values").AsGodotDictionary();if(audio.Call("needs_file_preview",Get(values,"audio")).AsBool())return true;if(edits.is_note_source(actor)&&(Get(values,"notes_dirty",false).AsBool()||Get(values,"rendered_signature","").AsString()!=edits.note_signature(actor,document)))return true;}var stacks=new GArray{Get(Dict(document,"master"),"effects",new GArray())};foreach(var raw in Items(document,"tracks")){var track=raw.AsGodotDictionary();if(Get(track,"sends",new GArray()).AsGodotArray().Count>0||Get(track,"solo",false).AsBool())return true;stacks.Add(Get(track,"effects",new GArray()));}foreach(var raw in Items(document,"actors")){var values=raw.AsGodotObject().Get("values").AsGodotDictionary();if(Get(Get(values,"automation",new Settings()).AsGodotDictionary(),"pitch",new GArray()).AsGodotArray().Count>0||Get(values,"reverse",false).AsBool())return true;stacks.Add(Get(values,"effects",new GArray()));}using var effects=new AudioEffectsOperations();foreach(var stack in stacks)foreach(var raw in stack.AsGodotArray()){var effect=raw.AsGodotDictionary();if(Get(effect,"enabled",true).AsBool()&&(!Get(effects.definition(Get(effect,"type","").AsString()),"realtime",false).AsBool()||Get(effect,"automation",new Settings()).AsGodotDictionary().Count>0))return true;}return false;
    }
    public void export_dialog(Control o)
    {
        var dialog=window(o,"Export audio",new Vector2I(550,500));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();var options=Dict(o,"_export_options").Duplicate(true);using var templates=new AudioTemplateOperations();var presets=templates.export_presets();var names=new GArray();foreach(var name in presets.Keys)names.Add(name);ChoiceAction(o,host,"Preset",names,"High Quality",value=>options.Merge(presets[value].AsGodotDictionary(),true));ChoiceAction(o,host,"Sample rate",new GArray{"44100","48000","96000"},options["sample_rate"].AsInt64().ToString(CultureInfo.InvariantCulture),value=>options["sample_rate"]=int.Parse(value,CultureInfo.InvariantCulture));ChoiceAction(o,host,"Bit depth",new GArray{"16","24","32"},options["bit_depth"].AsInt64().ToString(CultureInfo.InvariantCulture),value=>options["bit_depth"]=int.Parse(value,CultureInfo.InvariantCulture));NumberAction(o,host,"Bitrate (kbps)",options["bitrate"].AsDouble(),64,320,1,value=>options["bitrate"]=(int)value);CheckAction(host,"Mono",options["mono"].AsBool(),value=>options["mono"]=value);CheckAction(host,"Include effect tails",options["include_tail"].AsBool(),value=>options["include_tail"]=value);CheckAction(host,"Normalize loudness",options["normalize"].AsBool(),value=>options["normalize"]=value);NumberAction(o,host,"Target LUFS",Get(options,"target_lufs",-16).AsDouble(),-30,-8,.1,value=>options["target_lufs"]=value);var scope=ChoiceAction(o,host,"Range",new GArray{"Entire mix","Time selection","Selected clips","Selected track","Stems"},"Entire mix",_=>{});label(host,"Real WAV / MP3 / Ogg Vorbis / FLAC encoders. A safety limiter protects the output; loudness targets are optional. Effect tails are retained unless disabled.");ActionButton(host,"Choose destination",()=>{o.Set("_export_options",options.Duplicate(true));switch(scope.Selected){case 1:var selection=Field<Control>(o,"canvas").Get("time_selection").AsVector2();if(selection.Y<=selection.X){notice(o,"Select a time range first.");return;}options["start"]=selection.X;options["duration"]=selection.Y-selection.X;break;case 2:options["clip_ids"]=Items(Session(o),"selected_ids").Duplicate();break;case 3:options["track_id"]=Session(o).Get("selected_track");break;case 4:options["stems"]=true;break;}windowNode.QueueFree();o.Call("_choose_export",options);});
    }
    public Settings prepare_export(Control o,Settings options){using var renderer=new AudioRendererOperations();string error=renderer.selection_error(Document(o) as RefCounted,options);return PrepareExportResult(o,options,error);}
    private Settings PrepareExportResult(Control o,Settings options,string error){if(error.Length>0){notice(o,error);return new Settings();}return new Settings{["session"]=Session(o),["revision"]=Session(o).Get("revision"),["title"]=Document(o).Get("title")};}
    public string stem_destination(string destination,Settings track,Settings used)
    {
        string label=Get(track,"name","Track").AsString();using(var expression=new Expression()){if(expression.Parse("value.validate_filename()",new[]{"value"})==Error.Ok){var sanitized=expression.Execute(new GArray{label},null,false);if(!expression.HasExecuteFailed())label=sanitized.AsString();}}if(!label.IsValidFileName())foreach(char invalid in new[]{':','/','\\','?','*','"','|','%','<','>'})label=label.Replace(invalid,'_');if(label.Trim().Length==0)label="Track";string stem=destination.GetBaseName()+"_"+label,name=stem+"."+destination.GetExtension();int suffix=2;while(used.ContainsKey(name.ToLowerInvariant()))name=stem+"_"+(suffix++)+"."+destination.GetExtension();used[name.ToLowerInvariant()]=true;return name;
    }
    public void complete_export(Control o,Settings request,Settings target,Settings options)
    {
        if(Session(o)!=request["session"].AsGodotObject()||Session(o).Get("revision").AsInt64()!=request["revision"].AsInt64()){notice(o,"The composition changed while choosing a file. Repeat this action in the intended document.");return;}if(target.Count==0)return;string destination=Get(target,"path","").AsString();if(destination.Length==0)return;string error=Document(o).Call("midi_timing_error").AsString();if(error.Length>0){notice(o,error);return;}if(Get(options,"stems",false).AsBool()){var snapshot=Document(o).Call("snapshot").As<RefCounted>();Work(o,"export_stems",Session(o).Get("revision").AsInt64(),job=>{var results=new GArray();var used=new Settings();using var renderer=new AudioRendererOperations();using var lanes=new AudioAutomationLaneOperations();foreach(var raw in Items(snapshot,"tracks")){var track=raw.AsGodotDictionary();if(Get(track,"kind","").AsString()=="group"||lanes.is_lane(track)&&lanes.binding_error(snapshot,track["id"].AsString()).Length==0)continue;if(job.Call("is_cancelled").AsBool())break;var settings=options.Duplicate(true);settings["track_id"]=track["id"];results.Add(renderer.render(snapshot,stem_destination(destination,track,used),settings,job));}return new Settings{["results"]=results};});}else start_render(o,destination,options,"export");
    }
    public void start_render(Control o,string destination,Settings options,string action)
    {
        if(Recording(o).Get("active").AsBool())finish_automation_pass(o,"Render requested");string error=Document(o).Call("midi_timing_error").AsString();if(error.Length>0){if(action=="preview")o.Call("_cancel_exact_playback");notice(o,error);return;}if(_frameLanes.is_lane(Document(o).Call("track_for_id",Get(options,"track_id","").AsString()).AsGodotDictionary())){notice(o,"Select the linked audio track for a stem or bounce; automation lanes contain no audio clips.");return;}if(action=="preview"&&(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool())){notice(o,"Finish or cancel the take before starting another preview.");return;}var session=Session(o);var snapshot=Document(o).Call("snapshot").As<RefCounted>();var settings=options.Duplicate(true);var selection=Items(session,"selected_ids").Duplicate();string track=Get(options,"track_id",session.Get("selected_track")).AsString();double at=Position(o);if(action=="preview")settings["route_meters"]=true;ulong ownerId=session.GetInstanceId();var token=o.Get("_transport_token");long generation=session.Get("revision").AsInt64();o.Set("_render_generation",generation);if(action=="preview"){o.Set("_transport_requested",true);var playback=Field<Node>(o,"playback");playback.Set("exact_pending",true);playback.Set("playing",false);}else if(o.Get("_transport_requested").AsBool())o.Call("_cancel_exact_playback");Work(o,"render",generation,job=>{using var renderer=new AudioRendererOperations();var result=renderer.render(snapshot,destination,settings,job);result["action"]=action;result["selection"]=selection;result["track_id"]=track;result["at"]=Get(settings,"start",at).AsDouble();result["monitor_from"]=Get(settings,"monitor_from",result["at"]).AsDouble();result["owner_id"]=ownerId;result["transport_token"]=token;if(Get(result,"success",false).AsBool()&&action=="preview"){result["file_preview"]=true;using var pcm=new AudioPcmFileOperations();result["pcm_info"]=pcm.inspect(destination);}else if(Get(result,"success",false).AsBool()&&action!="export")result["stream"]=workspace_source(destination)!;return result;});
    }
    public string temporary_audio(string label){string directory=ProjectSettings.GlobalizePath("user://audio_workspace/rendered");DirAccess.MakeDirRecursiveAbsolute(directory);using var crypto=new Crypto();return directory.PathJoin(label+"_"+Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant()+".wav");}
